use serde_json::Value;

#[derive(Debug)]
pub enum Event {
    Click { x: i32, y: i32 },
    Scroll { delta: i32 },
}

pub fn parse(raw: &str) -> Option<Event> {
    let value: Value = serde_json::from_str(raw).ok()?;
    match value.get("type")?.as_str()? {
        "click" => Some(Event::Click {
            x: value.get("x")?.as_i64()? as i32,
            y: value.get("y")?.as_i64()? as i32,
        }),
        "scroll" => Some(Event::Scroll {
            delta: value.get("delta")?.as_i64()? as i32,
        }),
        _ => None,
    }
}

